 blackSun:'uabs.loc.black_sun_facility',chopper:'uabs.loc.choppers',umbra:'uabs.loc.umbra_club',spyder:'uabs.loc.spyder',zelcomm:'uabs.loc.zelcomm_tower',works:'uabs.loc.sector_943',novacore:'uabs.loc.novacore_factory',hideout:'uabs.loc.kaato_hideout'
