export function advanceUnderBlackSun(world,choiceId){const next=seedUnderBlackSunWorld(world);const p=next.publishedAdventure;if(p.status!=='active')throw new Error('A aventura publicada não está ativa.');ensureSystems(p);const node=UNDER_BLACK_SUN.nodes[p.currentNodeId];if(!node)throw new Error('Nó atual da aventura não existe.');const choice=(node.choices||[]).find(c=>c.id===String(choiceId));if(!choice||!conditionOk(choice,p))throw new Error('Escolha indisponível neste ponto da aventura.');const fromNodeId=p.currentNodeId;const effects={...(choice.effects||{})};const obligationDelta=Math.max(0,Number(effects.obligationPendingDelta)||0);delete effects.obligationPendingDelta;p.flags={...(p.flags||{}),...effects};if(obligationDelta>0)addPendingObligation(p,choice.id==='zelcomm-weapons'?'zelcomm':String(choice.id||'choice'),obligationDelta);if(choice.id==='zelcomm-weapons'){p.systems.zelcomm.alert=clamp(Number(p.systems.zelcomm.alert||0)+2,0,6);p.systems.zelcomm.lockdown=p.systems.zelcomm.alert>=4;if(p.systems.zelcomm.lockdown)p.flags.zelcommAlarmed=true}const target=UNDER_BLACK_SUN.nodes[choice.to];if(!target)throw new Error('Destino da aventura não existe.');p.currentNodeId=choice.to;appendSceneJournal(p,{fromNodeId,toNodeId:choice.to,choiceId:choice.id,choiceLabel:choice.label,effects:choice.effects||{}});if(!p.visitedNodeIds.includes(choice.to))p.visitedNodeIds.push(choice.to);if(['umbra-club','spyder','zelcomm-tower'].includes(choice.to)&&!p.investigationLocations.includes(choice.to))p.investigationLocations.push(choice.to);revealCurrentNodeNpcs(next,target);p.updatedAt=now();if(choice.to==='epilogue'){p.status='completed';p.completedAt=now();applyEpilogueConsequences(next,p)}next.publishedAdventure=p;return {world:next,progress:playerProgressSnapshot(p),node:playerNode(target,p),choiceEffects:sanitizePlayerFlags(choice.effects||{}),completed:p.status==='completed'}}
export function currentUnderBlackSunEncounter(world){const p=world?.publishedAdventure;if(!p||p.id!==ID||p.status!=='active')return null;ensureSystems(p);const history=p.systems.encounters.history||[];let id=null,label=null,preparation=null;if(p.currentNodeId==='hot-pursuit'){id='black-sun-pursuers';label='Perseguidores da Black Sun'}else if(p.currentNodeId==='showdown'){id='kaato-showdown';label='Confronto com Kaa’to';if(p.flags?.trapPrepared)preparation='Armadilha preparada: Kaa’to começa pressionado e mais perto do grupo.';else if(p.flags?.counterAmbushReady)preparation='Contraemboscada preparada: o grupo reduziu a vantagem de posição de Kaa’to.';else if(p.flags?.blackSunAgainstKaato)preparation='Pressão da Black Sun reduz as opções de Kaa’to.';else if(p.flags?.kaatoAlerted)preparation='Kaa’to está alertado e tenta iniciar o confronto à distância.'}if(!id)return null;const resolved=history.some(x=>x.encounterId===id&&x.outcome);return {id,label,preparation,available:!resolved,status:resolved?'resolved':(p.systems.encounters.activeId===id?'active':'ready')};}
export function underBlackSunEncounterSpec(world,encounterId=null){const next=seedUnderBlackSunWorld(world);const p=next.publishedAdventure;const current=currentUnderBlackSunEncounter(next);const id=String(encounterId||current?.id||'');if(!current||id!==current.id||!current.available)throw new Error('Encontro publicado indisponível neste ponto.');if(id==='black-sun-pursuers')return {id,label:'Perseguidores da Black Sun',playerInitiativeSkill:'alerta',npcInitiativeSkill:'alerta',adversaries:[{profileKey:'black_sun_enforcer',count:3,range:'Médio'}]};if(id==='kaato-showdown'){const prepared=Boolean(p.flags?.trapPrepared||p.flags?.counterAmbushReady||p.flags?.blackSunAgainstKaato);const range=p.flags?.kaatoAlerted&&!prepared?'Longo':prepared?'Curto':'Médio';const preWounds=(p.flags?.trapPrepared?2:0)+(p.flags?.blackSunAgainstKaato?1:0);const hazard=Number(p.systems?.novacore?.hazard||0);const setbacks=Math.min(2,Math.floor(hazard/2));return {id,label:'Kaa’to Leeachos',playerInitiativeSkill:'frialdad',npcInitiativeSkill:'frialdad',preparation:prepared?'As pistas reunidas deram ao grupo uma vantagem concreta na abertura do confronto.':hazard>=4?'Falhas na infiltração deixaram a planta em estado crítico; Kaa’to usa o caos e os alarmes a seu favor.':'Kaa’to entra no confronto sem uma desvantagem preparada pelo grupo.',playerSetbackDice:setbacks,adversaries:[{profileKey:'kaato_leeachos',worldNpcId:NPC.kaato,range,preWounds}]}};throw new Error('Encontro publicado desconhecido.');}
export function markUnderBlackSunEncounterActive(world,encounterId){const next=seedUnderBlackSunWorld(world);const p=next.publishedAdventure;ensureSystems(p);const current=currentUnderBlackSunEncounter(next);const id=String(encounterId||current?.id||'');if(!current||!current.available||id!==current.id)throw new Error('Encontro publicado indisponível neste ponto.');const activeId=String(p.systems.encounters.activeId||'');if(activeId&&activeId!==id)throw new Error('Outro encontro publicado já está ativo.');p.systems.encounters.activeId=id;p.updatedAt=now();return next}
export function recordUnderBlackSunEncounterOutcome(world,{encounterId,outcome,adversaries=[]}={}){const next=seedUnderBlackSunWorld(world);const p=next.publishedAdventure;ensureSystems(p);const current=currentUnderBlackSunEncounter(next);const id=String(encounterId||p.systems.encounters.activeId||current?.id||'');if(!id)return {world:next,record:null};if(!current||id!==current.id)throw new Error('Resultado de encontro incompatível com a cena atual.');if(!current.available)throw new Error('Encontro publicado indisponível neste ponto.');const activeId=String(p.systems.encounters.activeId||'');if(activeId&&activeId!==id)throw new Error('Resultado de encontro incompatível com o encontro ativo.');const summary=(adversaries||[]).map(a=>({id:a.id??null,worldNpcId:a.worldNpcId??null,profileKey:a.profileKey??null,status:a.status??'active',wounds:Number(a.wounds?.current ?? a.wounds ?? 0)}));const record={at:now(),nodeId:p.currentNodeId,encounterId:id,outcome:outcome||'ended',adversaries:summary};p.systems.encounters.history=[...(p.systems.encounters.history||[]),record].slice(-20);p.systems.encounters.activeId=null;p.flags.lastEncounter={encounterId:id,outcome:record.outcome};if(id==='black-sun-pursuers'){p.flags.blackSunPursuitFought=true;if(record.outcome==='adversaries_defeated')p.flags.momentum=clamp(Number(p.flags.momentum||0)+1,0,6);else p.flags.alertClock=clamp(Number(p.flags.alertClock||0)+1,0,6)}if(id==='kaato-showdown'){const kaato=summary.find(a=>a.worldNpcId===NPC.kaato||a.profileKey==='kaato_leeachos');if(kaato?.status==='incapacitated'||record.outcome==='adversaries_defeated')p.flags.kaatoNeutralized=true}p.updatedAt=now();next.publishedAdventure=p;return {world:next,record:clone(record)}}
export function markUnderBlackSunRewardsApplied(world,details={}){const next=clone(world);next.publishedAdventureRewards={...(next.publishedAdventureRewards||{})};next.publishedAdventureRewards[ID]={applied:true,appliedAt:now(),credits:Number(details.credits)||0,obligationAdded:Number(details.obligationAdded)||0,obligationReduced:Number(details.obligationReduced)||0,note:details.note||null};if(next?.publishedAdventure?.id===ID){next.publishedAdventure.rewardsApplied=true;next.publishedAdventure.updatedAt=now()}return next}
export function archiveUnderBlackSun(world){const next=clone(world);const p=next?.publishedAdventure;if(!p||p.id!==ID||p.status!=='completed')throw new Error('Sob um Sol Negro precisa estar concluída antes de continuar no mundo livre.');p.status='archived';p.archivedAt=now();p.updatedAt=now();next.publishedAdventure=p;return next}
